#include "stdlib/math/base/special/vercos.h"
#include "stdlib/math/base/special/abs2.h"
#include "stdlib/math/base/special/cos.h"

/**
* Computes the versed cosine.
*
* ## Method
*
* Evaluating the textbook formula
*
* ```tex
* \operatorname{vercos}(x) = 1 + \cos(x)
* ```
*
* loses significant digits when `cos(x)` is close to negative one (i.e., for `x` near odd multiples of π). Accordingly, we use the equivalent half-angle identity
*
* ```tex
* \operatorname{vercos}(x) = 2 \cos^2\left(\tfrac{x}{2}\right)
* ```
*
* which does not suffer from cancellation.
*
* @param x    input value (in radians)
* @return     versed cosine
*
* @example
* double y = stdlib_base_vercos( 3.141592653589793 / 2.0 );
* // returns 1.0
*/
double stdlib_base_vercos( const double x ) {
	return 2.0 * stdlib_base_abs2( stdlib_base_cos( x / 2.0 ) );
}
